<?php $canAccounts=in_array('accounts.view',$role_permissions??[],true);$canKyc=in_array('kyc.view',$role_permissions??[],true); ?>
<?php $sortUrl=static function(string $key):string{$query=$_GET;$query['sort']=$key;$query['direction']=isset($_GET['sort'])&&$_GET['sort']===$key&&strtolower((string)($_GET['direction']??'desc'))==='asc'?'desc':'asc';$query['page']=1;return admin_url('users?'.http_build_query($query));}; ?>
<div class="admin-table-scroll"><table class="admin-table admin-data-table"><thead><tr><th scope="col"><a class="admin-sort-link" href="<?= e($sortUrl('name')) ?>" data-list-page>User</a></th><th scope="col">Country</th><th scope="col"><a class="admin-sort-link" href="<?= e($sortUrl('created')) ?>" data-list-page>Registered</a></th><th scope="col"><a class="admin-sort-link" href="<?= e($sortUrl('status')) ?>" data-list-page>Status</a></th><?php if($canKyc): ?><th scope="col">Verification</th><?php endif; ?><?php if($canAccounts): ?><th scope="col">Demo Account</th><th scope="col"><a class="admin-sort-link" href="<?= e($sortUrl('balance')) ?>" data-list-page>Latest Virtual Balance</a></th><th scope="col">Open Positions</th><?php endif; ?><th scope="col"><a class="admin-sort-link" href="<?= e($sortUrl('last_login')) ?>" data-list-page>Last Login</a></th><th scope="col"><span class="sr-only">Action</span></th></tr></thead><tbody>
<?php if(!empty($users)): foreach($users as $user): ?><tr>
    <td data-label="User"><a class="admin-user-cell" href="<?= e(admin_url('users/'.$user['user_reference'])) ?>"><strong><?= e(trim($user['first_name'].' '.$user['last_name'])) ?></strong><small><?= e($user['email']) ?> · <?= e($user['user_reference']) ?></small></a></td>
    <td data-label="Country"><?= e($user['country']??'—') ?></td><td data-label="Registered"><?= e(App\Services\DashboardService::formatDate($user['created_at'])) ?></td>
    <td data-label="Status"><span class="admin-status-badge status-<?= e($user['status']) ?>"><?= e(ucwords(str_replace('_',' ',$user['status']))) ?></span></td>
    <?php if($canKyc): ?><td data-label="Verification"><span class="admin-status-badge status-<?= e($user['verification_status']??'not_submitted') ?>"><?= e(ucwords(str_replace('_',' ',$user['verification_status']??'not_submitted'))) ?></span></td><?php endif; ?>
    <?php if($canAccounts): ?><td data-label="Demo Account"><?php if(!empty($user['account_number'])): ?><a class="admin-row-link" href="<?= e(admin_url('accounts/'.$user['account_number'])) ?>"><?= e($user['account_number']) ?></a><small class="admin-cell-subtext"><?= (int)$user['account_count'] ?> account(s) · <?= e($user['account_status']) ?></small><?php else: ?>—<?php endif; ?></td><td data-label="Latest Virtual Balance"><?= $user['account_balance']!==null?e(App\Services\DashboardService::formatMoney((string)$user['account_balance'],(string)$user['account_currency'])):'—' ?></td><td data-label="Open Positions"><?= e($user['open_positions']??'—') ?></td><?php endif; ?>
    <td data-label="Last Login"><?= e(App\Services\DashboardService::formatDate($user['last_login_at'])) ?></td><td data-label="Action"><a class="admin-row-link" href="<?= e(admin_url('users/'.$user['user_reference'])) ?>">View user</a></td>
</tr><?php endforeach; else: ?><tr><td class="admin-table-empty" colspan="<?= $canAccounts?($canKyc?10:9):($canKyc?7:6) ?>"><strong>No users match these filters.</strong><span>Adjust the search or filters and try again.</span></td></tr><?php endif; ?>
</tbody></table></div>
